import React, { useState, useContext, useEffect } from "react";
import { NavLink, useNavigate, useLocation, Link } from "react-router-dom";
import {
  Menu,
  X,
  LogOut,
  LayoutDashboard,
  Sparkles,
  Users,
  Calendar,
  BookOpen,
  GraduationCap,
  Inbox,
  Settings,
  Globe,
  ShieldCheck,
  CheckCircle2,
} from "lucide-react";
import { AuthContext } from "../Context/AuthContext";
import logo from "../images/logo.png";
import EnrollmentModal from "./EnrollmentModal";
import api from "../api/axios";

const Navbar = () => {
  const { isAuth, user, logoutUser } = useContext(AuthContext);
  const navigate = useNavigate();
  const location = useLocation();
  const [isOpen, setIsOpen] = useState(false);
  const [enrollModalOpen, setEnrollModalOpen] = useState(false);
  const [pendingInquiriesCount, setPendingInquiriesCount] = useState(0);

  // Check if admin is currently logged in
  const isAdmin = isAuth && (user?.role === "ADMIN" || user?.role === "SUPER_ADMIN");
  const isTeacher = isAuth && user?.role === "TEACHER";
  const isParent = isAuth && user?.role === "PARENT";
  const isStudent = isAuth && user?.role === "STUDENT";
  const isOnAdminPage = location.pathname.startsWith("/admin");

  // Fetch pending inquiries count for admin notification badge
  useEffect(() => {
    if (isAdmin) {
      const fetchInquiryCount = async () => {
        try {
          const res = await api.get("/enrollments");
          if (res.data.success) {
            const pending = res.data.data.filter((e) => e.status === "PENDING").length;
            setPendingInquiriesCount(pending);
          }
        } catch (err) {
          // silent fallback
        }
      };
      fetchInquiryCount();
    }
  }, [isAdmin, location.pathname]);

  const publicLinks = [
    { to: "/", label: "Home" },
    { to: "/courses", label: "Courses & Classes" },
    { to: "/teachers", label: "Faculty" },
    { to: "/about", label: "About Us" },
  ];

  const adminTabs = [
    { id: "OVERVIEW", label: "Overview", icon: LayoutDashboard },
    { id: "ENROLLMENTS", label: "Inquiries", icon: Inbox, badge: pendingInquiriesCount },
    { id: "BATCHES", label: "Batches & Timetable", icon: Calendar },
    { id: "STUDENTS", label: "Students & Parents", icon: Users },
    { id: "TEACHERS", label: "Faculty Directory", icon: GraduationCap },
    { id: "CLASSES", label: "Classes & Syllabus", icon: BookOpen },
    { id: "SETTINGS", label: "Settings", icon: Settings },
  ];

  const getDashboardPath = () => {
    if (!user) return "/login";
    switch (user.role) {
      case "ADMIN":
      case "SUPER_ADMIN":
        return "/admin";
      case "TEACHER":
        return "/teacher";
      case "PARENT":
        return "/parent";
      case "STUDENT":
        return "/student";
      default:
        return "/";
    }
  };

  const handleLogout = () => {
    logoutUser();
    navigate("/");
    setIsOpen(false);
  };

  const handleAdminTabClick = (tabId) => {
    navigate(`/admin?tab=${tabId}`);
    setIsOpen(false);
  };

  // Get active tab from URL query param
  const queryParams = new URLSearchParams(location.search);
  const currentAdminTab = queryParams.get("tab") || "OVERVIEW";

  return (
    <>
      <header className="bg-[#d49539] sticky top-0 z-40 shadow-md">
        {/* Main Top Navigation Tier */}
        <div className="max-w-7xl mx-auto px-4 md:px-8 lg:px-12 py-3 flex items-center justify-between h-[82px]">
          {/* Logo & Institute Brand */}
          <div
            className="cursor-pointer flex items-center gap-3"
            onClick={() => navigate(isAdmin ? "/admin" : "/")}
          >
            <img src={logo} alt="Success Mentor logo" className="h-[52px] object-contain" />
            {isAdmin && (
              <div className="hidden sm:block pl-2.5 border-l border-[#304b62]/30 text-left">
                <span className="text-[11px] font-black uppercase tracking-wider text-[#304b62] block leading-tight">
                  Admin Command Hub
                </span>
                <span className="text-xs font-bold text-white/90">Apex Academy</span>
              </div>
            )}
          </div>

          {/* Desktop Middle Links (Public vs Role-Aware) */}
          <nav className="hidden md:flex items-center gap-1 lg:gap-4">
            {!isAdmin ? (
              // Public Marketing Nav
              publicLinks.map((link) => {
                const isActive = location.pathname === link.to;
                return (
                  <NavLink
                    to={link.to}
                    key={link.to}
                    className="relative py-2 px-3 font-bold text-sm lg:text-base text-[#304b62] hover:opacity-85 transition-colors"
                  >
                    {link.label}
                    {isActive && (
                      <span className="absolute bottom-[-6px] left-0 right-0 h-[4px] bg-[#304b62] rounded-t-md" />
                    )}
                  </NavLink>
                );
              })
            ) : (
              // Admin Quick Actions in Header
              <div className="flex items-center gap-2">
                <button
                  onClick={() => navigate(isOnAdminPage ? "/courses" : "/admin")}
                  className="bg-white/20 hover:bg-white/30 text-[#304b62] font-bold px-3.5 py-1.5 rounded-xl text-xs flex items-center gap-1.5 transition-colors"
                >
                  <Globe size={14} />
                  <span>{isOnAdminPage ? "View Public Site" : "Open Admin Portal"}</span>
                </button>

                <button
                  onClick={() => navigate("/admin?tab=ENROLLMENTS")}
                  className="bg-white/20 hover:bg-white/30 text-[#304b62] font-bold px-3 py-1.5 rounded-xl text-xs flex items-center gap-1.5 transition-colors relative"
                >
                  <Inbox size={14} />
                  <span>Inquiries</span>
                  {pendingInquiriesCount > 0 && (
                    <span className="bg-[#304b62] text-white text-[10px] font-black px-1.5 py-0.2 rounded-full">
                      {pendingInquiriesCount}
                    </span>
                  )}
                </button>
              </div>
            )}
          </nav>

          {/* Right Action / Auth Buttons */}
          <div className="hidden md:flex items-center gap-3">
            {isAuth ? (
              <div className="flex items-center gap-2.5">
                {/* User Role Pill */}
                <Link
                  to={getDashboardPath()}
                  className="bg-[#304b62] hover:bg-[#253b4e] text-white font-bold px-4 py-2 rounded-xl text-xs flex items-center gap-2 shadow-sm transition-all"
                >
                  {isAdmin ? (
                    <ShieldCheck size={15} className="text-[#d49539]" />
                  ) : (
                    <LayoutDashboard size={15} className="text-[#d49539]" />
                  )}
                  <div className="text-left">
                    <span className="block text-[10px] text-[#f6d6a0] uppercase tracking-wider font-extrabold leading-none">
                      {user?.role}
                    </span>
                    <span className="block font-bold truncate max-w-[130px] leading-tight">
                      {user?.name || "Portal User"}
                    </span>
                  </div>
                </Link>

                {/* Logout Button */}
                <button
                  onClick={handleLogout}
                  title="Log Out"
                  className="p-2.5 bg-white/20 hover:bg-white/30 text-[#304b62] rounded-xl transition-colors"
                >
                  <LogOut size={17} />
                </button>
              </div>
            ) : (
              <div className="flex items-center gap-3">
                <button
                  onClick={() => navigate("/login")}
                  className="bg-white/20 hover:bg-white/30 text-[#304b62] font-extrabold px-4 py-2 rounded-xl text-sm transition-colors"
                >
                  Log In
                </button>
                <button
                  onClick={() => setEnrollModalOpen(true)}
                  className="bg-[#304b62] hover:bg-[#253b4e] text-white font-bold px-5 py-2.5 rounded-xl transition-colors shadow-md text-sm flex items-center gap-1.5"
                >
                  <Sparkles size={15} /> Admission Now
                </button>
              </div>
            )}
          </div>

          {/* Mobile Hamburger Button */}
          <button
            onClick={() => setIsOpen(!isOpen)}
            className="md:hidden p-2 text-[#304b62] hover:bg-black/10 rounded-lg focus:outline-none"
            aria-label="Toggle Navigation Menu"
          >
            {isOpen ? <X size={26} /> : <Menu size={26} />}
          </button>
        </div>

        {/* Dedicated Admin Sub-Nav Bar (Visible on /admin or for Admin users) */}
        {isAdmin && (
          <div className="bg-[#304b62] border-t border-black/10 px-4 md:px-8 lg:px-12 py-2 overflow-x-auto shadow-inner">
            <div className="max-w-7xl mx-auto flex items-center gap-1.5 md:gap-2 min-w-max">
              {adminTabs.map((tab) => {
                const Icon = tab.icon;
                const isActive = isOnAdminPage && currentAdminTab === tab.id;

                return (
                  <button
                    key={tab.id}
                    onClick={() => handleAdminTabClick(tab.id)}
                    className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all flex items-center gap-1.5 shrink-0 ${
                      isActive
                        ? "bg-[#d49539] text-white shadow-sm scale-105"
                        : "text-slate-200 hover:bg-white/10 hover:text-white"
                    }`}
                  >
                    <Icon size={14} className={isActive ? "text-white" : "text-[#d49539]"} />
                    <span>{tab.label}</span>
                    {tab.badge > 0 && (
                      <span className="bg-red-500 text-white text-[10px] font-black px-1.5 py-0.2 rounded-full animate-pulse">
                        {tab.badge}
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* Mobile Drawer */}
        {isOpen && (
          <div className="fixed inset-0 z-50 md:hidden flex justify-end animate-fadeIn">
            <div className="fixed inset-0 bg-black/50" onClick={() => setIsOpen(false)} />
            <div className="relative w-80 bg-[#d49539] h-full p-6 shadow-2xl flex flex-col z-10 space-y-4 overflow-y-auto">
              <div className="flex justify-between items-center pb-3 border-b border-[#304b62]/20">
                <div>
                  <span className="font-black text-xl text-[#304b62] block">Success Mentor</span>
                  {isAdmin && <span className="text-xs font-bold text-white">Admin Management</span>}
                </div>
                <button onClick={() => setIsOpen(false)} className="p-1 text-[#304b62]">
                  <X size={24} />
                </button>
              </div>

              {/* Admin Mobile Tabs */}
              {isAdmin ? (
                <div className="space-y-1.5">
                  <div className="text-[11px] font-bold text-[#304b62] uppercase tracking-wider mb-2">
                    Administration Modules:
                  </div>
                  {adminTabs.map((tab) => {
                    const Icon = tab.icon;
                    return (
                      <button
                        key={tab.id}
                        onClick={() => handleAdminTabClick(tab.id)}
                        className={`w-full text-left p-2.5 rounded-xl text-xs font-bold flex items-center justify-between transition-colors ${
                          currentAdminTab === tab.id
                            ? "bg-[#304b62] text-white"
                            : "bg-white/20 text-[#304b62] hover:bg-white/30"
                        }`}
                      >
                        <div className="flex items-center gap-2">
                          <Icon size={16} className={currentAdminTab === tab.id ? "text-[#d49539]" : "text-[#304b62]"} />
                          <span>{tab.label}</span>
                        </div>
                        {tab.badge > 0 && (
                          <span className="bg-red-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full">
                            {tab.badge}
                          </span>
                        )}
                      </button>
                    );
                  })}

                  <div className="pt-3 border-t border-[#304b62]/20 space-y-2">
                    <button
                      onClick={() => {
                        navigate("/courses");
                        setIsOpen(false);
                      }}
                      className="w-full bg-white/20 text-[#304b62] font-bold py-2 rounded-xl text-xs flex items-center justify-center gap-1.5"
                    >
                      <Globe size={14} /> View Public Website
                    </button>
                    <button
                      onClick={handleLogout}
                      className="w-full bg-red-600 text-white font-bold py-2 rounded-xl text-xs flex items-center justify-center gap-1.5"
                    >
                      <LogOut size={14} /> Log Out Admin
                    </button>
                  </div>
                </div>
              ) : (
                /* Public Mobile Links */
                <div className="flex flex-col gap-2">
                  {publicLinks.map((link) => (
                    <NavLink
                      to={link.to}
                      key={link.to}
                      onClick={() => setIsOpen(false)}
                      className="font-bold text-base py-2 px-3 rounded-lg text-[#304b62] hover:bg-black/10"
                    >
                      {link.label}
                    </NavLink>
                  ))}

                  {isAuth ? (
                    <>
                      <Link
                        to={getDashboardPath()}
                        onClick={() => setIsOpen(false)}
                        className="bg-[#304b62] text-white font-bold py-2.5 px-4 rounded-xl text-center text-sm mt-3"
                      >
                        Open Dashboard ({user?.role})
                      </Link>
                      <button
                        onClick={handleLogout}
                        className="bg-white/20 text-[#304b62] font-bold py-2 px-4 rounded-xl text-center text-sm"
                      >
                        Log Out
                      </button>
                    </>
                  ) : (
                    <>
                      <button
                        onClick={() => {
                          navigate("/login");
                          setIsOpen(false);
                        }}
                        className="w-full mt-3 bg-white/20 text-[#304b62] font-bold py-2.5 rounded-xl text-sm"
                      >
                        Log In
                      </button>
                      <button
                        onClick={() => {
                          setEnrollModalOpen(true);
                          setIsOpen(false);
                        }}
                        className="w-full bg-[#304b62] text-white font-bold py-2.5 rounded-xl text-sm"
                      >
                        Admission Now
                      </button>
                    </>
                  )}
                </div>
              )}
            </div>
          </div>
        )}
      </header>

      {/* Global Enrollment Modal from Navbar */}
      <EnrollmentModal
        isOpen={enrollModalOpen}
        onClose={() => setEnrollModalOpen(false)}
        preselectedClass={10}
        preselectedCourse="General Admission Inquiry"
      />
    </>
  );
};

export default Navbar;
